const s86x = interpolate(frame, sf(0,20), [width*0.5, width*0.87], cl);
const s86y = interpolate(frame, sf(0,20), [height*0.45, height*0.09], cl);
const s86p = 0.4 + 0.25 * Math.sin(frame * 0.12);

const letPxN = 40;
const letPx = Array.from({length:letPxN}, (_,i) => {
  const ang = rng(i) * Math.PI * 2;
  const r0 = 500 + rng(i+50)*500;
  const sx = width*0.5 + Math.cos(ang)*r0;
  const sy = height*0.25 + Math.sin(ang)*r0;
  const ex = width*0.5 + (rng(i+100)-0.5)*180;
  const ey = height*0.25 + (rng(i+150)-0.5)*50;
  const px = interpolate(frame, sf(10,28), [sx, ex], cl);
  const py = interpolate(frame, sf(10,28), [sy, ey], cl);
  const op = Math.min(
    interpolate(frame, sf(10,14), [0,1], cl),
    interpolate(frame, sf(24,28), [1,0], cl)
  );
  const sz = 3 + rng(i+200)*5;
  return e('div',{key:'lp'+i,style:{
    position:'absolute', left:px-sz/2, top:py-sz/2,
    width:sz, height:sz, background:D.white, opacity:op,
  }});
});
const letOp = interpolate(frame, sf(25,30), [0,1], cl);

const meBlur = interpolate(frame, sf(32,46), [20,0], cl);
const meOp = interpolate(frame, sf(32,46), [0,1], cl);

const showSp = spring({frame:Math.max(0,frame-50), fps, config:{damping:8,stiffness:220}});
const showTY = interpolate(showSp, [0,1], [-350,0], cl);
const showOp = frame >= 50 ? 1 : 0;

const youOp = interpolate(frame, sf(62,67), [0,1], cl);

const ringProg = interpolate(frame, sf(95,112), [0,1], cl);
const ringR = ringProg * Math.hypot(width,height) * 0.7;
const ringOp = frame >= 95 ? interpolate(frame, sf(95,112), [1,0], cl) : 0;
const ringW = interpolate(frame, sf(95,112), [4,1], cl);

const blackOp = interpolate(frame, sf(113,115), [0,1], cl);

const ws = {
  position:'absolute', left:0, right:0, textAlign:'center',
  fontFamily:D.font_display, fontWeight:900, fontSize:Math.min(width*0.12, 130),
  letterSpacing:8, color:D.white,
};

return e(AbsoluteFill, {style:{background:D.bg}},
  e('div',{style:{
    position:'absolute', left:s86x, top:s86y,
    transform:'translate(-50%,-50%) scale('+s86s+')',
    fontFamily:D.font_mono, fontSize:90, fontWeight:900,
    color:D.red, opacity:s86p,
    textShadow:'0 0 20px '+D.red+', 0 0 40px '+D.red,
  }}, '86%'),
  ...letPx,
  e('div',{style:{...ws, top:height*0.2, opacity:letOp}}, 'LET'),
  e('div',{style:{...ws, top:height*0.37, opacity:meOp, filter:'blur('+meBlur+'px)'}}, 'ME'),
  e('div',{style:{...ws, top:height*0.54, opacity:showOp, transform:'translateY('+showTY+'px)'}}, 'SHOW'),
  e('div',{style:{...ws, top:height*0.71, opacity:youOp}}, 'YOU'),
  ringOp > 0 ? e('div',{style:{
    position:'absolute',
    left:width/2 - ringR, top:height/2 - ringR,
    width:ringR*2, height:ringR*2, borderRadius:'50%',
    border:ringW+'px solid '+D.red, opacity:ringOp,
    boxShadow:'0 0 40px '+D.red+', 0 0 80px '+D.red+', inset 0 0 40px '+D.red,
    pointerEvents:'none',
  }}) : null,
  e('div',{style:{position:'absolute',inset:0,background:D.bg,opacity:blackOp}})
);
